package com.nexusdrive.metadata.entity;import jakarta.persistence.*;import java.util.*;@Entity@Table(name="chunks",uniqueConstraints=@UniqueConstraint(columnNames={"file_id","chunk_index"}))public class Chunk{@Id private UUID id=UUID.randomUUID();@ManyToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="file_id")private FileMetadata file;@Column(name="chunk_index",nullable=false)private int chunkIndex;@Column(name="storage_key",nullable=false,updatable=false)private String storageKey;@Column(name="storage_node_id",nullable=false)private String storageNodeId;@Column(name="replica_node_ids",columnDefinition="text[]")private String[] replicaNodeIds=new String[0];@Column(length=64)private String checksum;@Column(nullable=false)private boolean uploaded;@Column(name="plain_size",nullable=false)private int plainSize;public UUID getId(){return id;}public FileMetadata getFile(){return file;}public void setFile(FileMetadata v){file=v;}public int getChunkIndex(){return chunkIndex;}public void setChunkIndex(int v){chunkIndex=v;}public String getStorageKey(){return storageKey;}public void setStorageKey(String v){storageKey=v;}public String getStorageNodeId(){return storageNodeId;}public void setStorageNodeId(String v){storageNodeId=v;}public String[] getReplicaNodeIds(){return replicaNodeIds;}public void setReplicaNodeIds(String[] v){replicaNodeIds=v;}public String getChecksum(){return checksum;}public void setChecksum(String v){checksum=v;}public boolean isUploaded(){return uploaded;}public void setUploaded(boolean v){uploaded=v;}public int getPlainSize(){return plainSize;}public void setPlainSize(int v){plainSize=v;}}
